    private static final String[][] MENU = {
        {"Admin", "Dashboard", "Kelola Pengguna", "Kelola Fasilitas", "Laporan Kerusakan", "Cari Laporan"},
        {"Supervisor", "Dashboard", "Penugasan Laporan", "Pantau Progres", "Cari Laporan", "Rekap Laporan"},
        {"Petugas", "Dashboard", "Tugas Saya", "Perbarui Progres", "Riwayat Progres", "Cari Laporan"}
    };
    private static final String[] AKSEN = {"2563EB", "7C3AED", "EA580C"};

    private String peran = "Admin";
    private int aktif = 0;
    private java.util.function.IntConsumer onMenu;
    private Runnable onLogout;

    private javax.swing.JButton[] menuButtons() {
        return new javax.swing.JButton[] {btnMenu1, btnMenu2, btnMenu3, btnMenu4, btnMenu5};
    }

    /** Peran: Admin, Supervisor atau Petugas (menentukan menu dan warna). */
    public String getPeran() {
        return peran;
    }

    public void setPeran(String peran) {
        this.peran = peran;
        terapkan();
    }

    /** Indeks menu yang sedang aktif (0 = Dashboard). */
    public int getAktif() {
        return aktif;
    }

    public void setAktif(int aktif) {
        this.aktif = aktif;
        terapkan();
    }

    public void setOnMenu(java.util.function.IntConsumer onMenu) {
        this.onMenu = onMenu;
    }

    public void setOnLogout(Runnable onLogout) {
        this.onLogout = onLogout;
    }

    private void terapkan() {
        int p = 0;
        for (int i = 0; i < MENU.length; i++) {
            if (MENU[i][0].equalsIgnoreCase(peran)) {
                p = i;
            }
        }
        java.awt.Color aksen = java.awt.Color.decode("#" + AKSEN[p]);
        lblLogoA.setBackground(aksen);
        lblPeran.setText("Peran: " + MENU[p][0]);
        javax.swing.JButton[] b = menuButtons();
        for (int i = 0; i < b.length; i++) {
            boolean on = (i == aktif);
            b[i].setText("\u2022  " + MENU[p][i + 1]);
            b[i].setBackground(on ? aksen : new java.awt.Color(15, 23, 42));
            b[i].setForeground(on ? java.awt.Color.WHITE : new java.awt.Color(203, 213, 225));
            b[i].setFont(b[i].getFont().deriveFont(on ? java.awt.Font.BOLD : java.awt.Font.PLAIN));
        }
    }

    private void klik(int indeks) {
        if (onMenu != null) {
            onMenu.accept(indeks);
        } else {
            setAktif(indeks);
        }
    }

